# Francis J. Yealy, s.j., Sainte Genevieve: The Story of Missouri's Oldest Settlement, Sainte-Geneviève, Bicentennial
# Historical Committee, 1935 (PDF du Drive de l'auteur, dossier SAINTE_GENEVIEVE_OLD_MINES_HISTORY ; texte lu jusqu'au ch. VI). Préfixe YE35.
from commun import Corpus
YE = "Yealy, Francis J. (1935), Sainte Genevieve: The Story of Missouri's Oldest Settlement, Sainte-Geneviève (Missouri), Bicentennial Historical Committee"
C = Corpus('Recherches', 'YE35', YE, page_fmt='{}')
F = C.F
F('01', "Le Grand Champ : la paroisse Saint-Joachim, premier nom de Sainte-Geneviève (1732)", 'etablissement', '1732', -90.035, 37.965, 'a', ['Jean-Paul Mercier', 'Louis Poulin'],
  "La tradition fixait la fondation de Sainte-Geneviève à 1735 ; deux cartes de 1755 et le mémoire du père Watrin suggéraient plutôt 1749-1752. Yealy retient une date plus ancienne : le 25 mai 1732, le père Mercier, supérieur de la mission de Cahokia, écrit au Séminaire de Québec qu'il a confié des papiers à « un certain Louis Poulin, de la paroisse Saint-Joachim ». Le premier village, au bord du fleuve face à Kaskaskia, s'appelait donc déjà Saint-Joachim ; en 1881, on y retrouva une margelle de puits gravée « 1732 ». Les mineurs qui, après la faillite de la Compagnie de Law (1720), portaient leur plomb au fleuve en furent sans doute les premiers habitants.",
  "ch. III, p. 21-28", "Point sur l'ancien site du Grand Champ, au sud de la ville actuelle ; le village a été emporté par le fleuve.")
F('02', "Sainte-Geneviève : le premier registre paroissial s'ouvre sur le mariage d'André de Guire dit La Rose (26 février 1759)", 'religion', '1759-02-26', -90.035, 37.965, 'c', ['André de Guire dit La Rose', 'Marie La Boissière', 'Jean-Baptiste de Guire dit La Rose'],
  "Les registres de Sainte-Geneviève commencent le 26 février 1759 par le mariage d'André de Guire dit La Rose et de Marie La Boissière, veuve de Joseph Baron. En 1825, le vieil habitant Julien Labruyère témoignera qu'un Baptiste La Rose, très âgé, avait été le premier colon du vieux village ; Yealy identifie deux Jean-Baptiste de Guire dit La Rose, l'un mort en 1773, l'autre, natif de Montréal, mort en 1781. La plus ancienne pièce connue du village est une vente de terrain de décembre 1754, de Laurent Gabourie à Jean-Baptiste Saint-Gemme Beauvais.",
  "ch. III, p. 28-31", "Point sur le site du vieux village.")
F('03', "Les Grandes Eaux de 1785 : Sainte-Geneviève monte aux Petites Côtes", 'evenement', '1785-04~/1794', -90.0498, 37.9806, 'c', ['François Vallé'],
  "Vers 1784, le fleuve ronge la berge du vieux village ; au printemps 1785, les « Grandes Eaux » submergent le village et ses terres de douze à quinze pieds. Les habitants rebâtissent sur les hauteurs, aux Petites Côtes, où presque toutes les maisons sont transportées dès 1787 ; le vieux site n'est abandonné qu'en 1791 et l'église, démontée, n'est remontée dans le nouveau village que trois ans plus tard. Le lieutenant-gouverneur Zenon Trudeau écrira en 1798 que les inondations tourmentaient le vieux village depuis plus de soixante ans.",
  "ch. III et VI", "Point au centre historique actuel de Sainte-Geneviève.")
F('04', "Sainte-Geneviève : réception solennelle de Mgr Du Bourg dans son diocèse (31 décembre 1818)", 'religion', '1818-12-31/1819-01-01', -90.0498, 37.9806, 'c', ['Louis-Guillaume-Valentin Du Bourg', 'Henri Pratte'],
  "Avant même Saint-Louis, c'est Sainte-Geneviève qui accueille officiellement l'évêque Du Bourg, le 31 décembre 1818. Quarante citoyens à cheval l'attendent au débarcadère et l'escortent jusqu'au presbytère ; toute la population, catholiques et protestants confondus, entend son discours à l'église. Le lendemain, il y célèbre sa première messe pontificale, avant d'être reçu à Saint-Louis le 5 janvier. Mgr Flaget avait d'ailleurs envisagé de fixer le siège épiscopal à Sainte-Geneviève plutôt qu'à Saint-Louis, où l'on venait d'ouvrir un théâtre.",
  "p. 102-103", "Fin du livre lue en entier en novembre 2026. Point dans la ville actuelle.")
F('05', "Sainte-Geneviève : ordination d'Hercule Brassac et de séminaristes des Barrens par Mgr Du Bourg (1er novembre 1819)", 'religion', '1819-11-01', -90.0498, 37.9806, 'c', ['Louis-Guillaume-Valentin Du Bourg', 'Hercule Brassac', 'François-Xavier Dahmen', 'Léo Deys', 'Casto Gonzalez', 'Henri Pratte'],
  "Le jour de la Toussaint 1819, la paroisse de l'abbé Henri Pratte assiste dans sa propre église à une cérémonie d'ordination. Mgr Du Bourg ordonne prêtre Hercule Brassac, futur vicaire général de Mgr Purcell à Cincinnati, diacre François-Xavier Dahmen, futur curé du lieu, et sous-diacres Léo Deys et Casto Gonzalez ; un autre reçoit les ordres mineurs et un dernier la tonsure. Tous sont des séminaristes du séminaire des Barrens, recrutés par l'évêque lors de son voyage en Europe. À la fin de l'année, les pères Niel, de Saint-Louis, et Desmoulins, de Kaskaskia, prêchent une mission dans la paroisse.",
  "p. 103", "Yealy écrit « avant la fin de l'année » qui suit le retour de l'abbé Pratte en janvier 1819, d'où la date du 1er novembre 1819.")
F('06', "Petit Canada (French Village) : halte des tournées de l'abbé Pratte et chapelle de mission (vers 1816-1838)", 'religion', '1816~/1838', -90.34, 37.985, 'a', ['Henri Pratte', 'François-Xavier Dahmen'],
  "En allant desservir l'église qu'il a bâtie à Old Mines, à soixante milles au nord-ouest de Sainte-Geneviève, l'abbé Henri Pratte, curé à partir d'octobre 1815, s'arrête probablement pour la nuit et dit la messe à une halte du chemin. C'est là que grandit le hameau du Petit Canada, ou French Village. En 1838, son successeur François-Xavier Dahmen y achève une nouvelle chapelle de mission.",
  "p. 101, 116", "Voir aussi la fiche ROT28-05 (paroisse de 1848-1858). Point au village actuel de French Village (comté de Saint-François).")
F('07', "Rivière aux Vases : une église pour une congrégation surtout française (1842)", 'religion', '1842', -89.98, 37.93, 'a', ['Brands'],
  "Alors que les immigrants allemands affluent dans la paroisse de Sainte-Geneviève et reçoivent leur propre église à Offenburg (Zell) en 1845, une église est dédiée en 1842 à la mission de la Rivière aux Vases. La congrégation y reste longtemps majoritairement française ; Yealy suppose qu'elle est desservie par le vicaire français, le père Brands. Une autre chapelle de mission est bénie en 1847 à la « Byrne-Charvin place », aujourd'hui Ozora, puis abandonnée.",
  "p. 117", "Point au hameau de Rivière aux Vases, au sud de Sainte-Geneviève.")
fiches = C.fiches
